package main

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// splitInput is a small stand-in for the output of oapi-codegen: models first, then the server
// starting at ServerInterface, with imports used by only one half each.
const splitInput = `//go:build go1.22

// Package rest provides primitives to interact with the openapi HTTP API.
//
// Code generated by github.com/oapi-codegen/oapi-codegen/v2 version v2.8.0 DO NOT EDIT.
package rest

import (
	"encoding/json"
	"net/http"
	"time"

	openapi_types "github.com/oapi-codegen/runtime/types"
)

// Thing is a model.
type Thing struct {
	At   time.Time          ` + "`json:\"at\"`" + `
	Mail openapi_types.Email ` + "`json:\"mail\"`" + `
}

// ServerInterface represents all server handlers.
type ServerInterface interface {
	// (GET /things)
	ListThings(w http.ResponseWriter, r *http.Request)
}

func encode(w http.ResponseWriter, t Thing) error { return json.NewEncoder(w).Encode(t) }
`

// importsOf parses src and returns its import paths and the names of its type declarations.
func importsOf(t *testing.T, name string, src []byte) (imports, types []string, f *ast.File) {
	t.Helper()
	f, err := parser.ParseFile(token.NewFileSet(), name, src, parser.ParseComments)
	if err != nil {
		t.Fatalf("%s does not parse: %v\n%s", name, err, src)
	}
	for _, s := range f.Imports {
		p, _ := strconv.Unquote(s.Path.Value)
		imports = append(imports, p)
	}
	for _, d := range f.Decls {
		if g, ok := d.(*ast.GenDecl); ok && g.Tok == token.TYPE {
			for _, s := range g.Specs {
				types = append(types, s.(*ast.TypeSpec).Name.Name)
			}
		}
	}
	return imports, types, f
}

func TestSplitRest_ModelsAndServer(t *testing.T) {
	models, server, objects, err := splitRest([]byte(splitInput))
	if err != nil {
		t.Fatal(err)
	}
	if _, types, _ := importsOf(t, "objects.gen.go", objects); len(types) != 0 {
		t.Errorf("objects types = %v, want none without a strict server", types)
	}
	mi, mt, mf := importsOf(t, "models.gen.go", models)
	si, st, sf := importsOf(t, "rest.gen.go", server)
	if want := []string{"github.com/oapi-codegen/runtime/types", "time"}; !slices.Equal(sortedCopy(mi), want) {
		t.Errorf("models imports = %v, want %v", mi, want)
	}
	if want := []string{"encoding/json", "net/http"}; !slices.Equal(sortedCopy(si), want) {
		t.Errorf("server imports = %v, want %v", si, want)
	}
	if !slices.Equal(mt, []string{"Thing"}) || !slices.Equal(st, []string{"ServerInterface"}) {
		t.Errorf("types: models %v, server %v; want [Thing] and [ServerInterface]", mt, st)
	}
	for name, f := range map[string]*ast.File{"models": mf, "server": sf} {
		if f.Name.Name != "rest" {
			t.Errorf("%s: package %s, want rest", name, f.Name.Name)
		}
	}
	for name, src := range map[string][]byte{"models": models, "server": server} {
		s := string(src)
		if !strings.HasPrefix(s, "//go:build go1.22\n") || !strings.Contains(s, "DO NOT EDIT.") {
			t.Errorf("%s lost the build constraint or the generated-code marker:\n%s", name, s)
		}
	}
	if !strings.Contains(string(server), "// ServerInterface represents all server handlers.") {
		t.Error("the server half lost the doc comment of ServerInterface")
	}
}

// TestSplitRest_NoServer: without ServerInterface everything is models and the server file holds
// only the package clause, so both files always exist.
func TestSplitRest_NoServer(t *testing.T) {
	models, server, objects, err := splitRest([]byte("package rest\n"))
	if err != nil {
		t.Fatal(err)
	}
	importsOf(t, "models.gen.go", models)
	if _, types, _ := importsOf(t, "rest.gen.go", server); len(types) != 0 {
		t.Errorf("server types = %v, want none", types)
	}
	if _, types, _ := importsOf(t, "objects.gen.go", objects); len(types) != 0 {
		t.Errorf("objects types = %v, want none", types)
	}
}

func TestSplitRest_RejectsInvalidGo(t *testing.T) {
	if _, _, _, err := splitRest([]byte("package rest\nfunc (")); err == nil {
		t.Fatal("splitRest = nil error for invalid Go")
	}
}

// TestRealRest_BelowMaxFileKB: each half of the real REST package stays below repo.max_file_kb
// (1024 KiB, docs/spec/23-qualitaet.md), the limit the hook check-added-large-files holds.
func TestRealRest_BelowMaxFileKB(t *testing.T) {
	for _, name := range []string{"models.gen.go", "rest.gen.go", "objects.gen.go", "objects2.gen.go"} {
		info, err := os.Stat(filepath.Join("..", "..", "rest", name))
		if err != nil {
			t.Fatal(err)
		}
		if info.Size() > 1024*1024 {
			t.Errorf("%s has %d bytes, above repo.max_file_kb", name, info.Size())
		}
	}
}

func sortedCopy(s []string) []string {
	c := slices.Clone(s)
	slices.Sort(c)
	return c
}

// splitStrictInput adds the strict server to splitInput: the request and response objects of
// an operation and the strict interface after them.
const splitStrictInput = splitInput + `
type ListThingsRequestObject struct {
	Since time.Time
}

// ListThings200JSONResponse is a response object.
type ListThings200JSONResponse []Thing

func (r ListThings200JSONResponse) VisitListThingsResponse(w http.ResponseWriter) error {
	return json.NewEncoder(w).Encode(r)
}

// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	ListThings(r ListThingsRequestObject) (ListThings200JSONResponse, error)
}

type strictHandler struct{ ssi StrictServerInterface }
`

// TestSplitRest_StrictObjects (INT-W17/4): the request and response objects of the strict server,
// from the first RequestObject to StrictServerInterface, go to objects.gen.go; the strict
// interface and handler stay with the server, and each file imports only what it uses.
func TestSplitRest_StrictObjects(t *testing.T) {
	models, server, objects, err := splitRest([]byte(splitStrictInput))
	if err != nil {
		t.Fatal(err)
	}
	_, mt, _ := importsOf(t, "models.gen.go", models)
	si, st, _ := importsOf(t, "rest.gen.go", server)
	oi, ot, _ := importsOf(t, "objects.gen.go", objects)
	if !slices.Equal(mt, []string{"Thing"}) {
		t.Errorf("models types = %v", mt)
	}
	if want := []string{"ServerInterface", "StrictServerInterface", "strictHandler"}; !slices.Equal(st, want) {
		t.Errorf("server types = %v, want %v", st, want)
	}
	if want := []string{"ListThingsRequestObject", "ListThings200JSONResponse"}; !slices.Equal(ot, want) {
		t.Errorf("objects types = %v, want %v", ot, want)
	}
	if want := []string{"encoding/json", "net/http"}; !slices.Equal(sortedCopy(si), want) {
		t.Errorf("server imports = %v, want %v", si, want)
	}
	if want := []string{"encoding/json", "net/http", "time"}; !slices.Equal(sortedCopy(oi), want) {
		t.Errorf("objects imports = %v, want %v", oi, want)
	}
	if !strings.Contains(string(objects), "// ListThings200JSONResponse is a response object.") ||
		!strings.Contains(string(server), "// StrictServerInterface represents all server handlers.") {
		t.Error("a doc comment did not move with its declaration")
	}
}

// splitTwoOpsInput has the objects of two operations before the strict interface, so
// halveObjects can cut between them.
var splitTwoOpsInput = strings.Replace(splitStrictInput, "// StrictServerInterface represents", `type GetThingRequestObject struct {
	ID string
}

// GetThing200JSONResponse is a response object.
type GetThing200JSONResponse Thing

func (r GetThing200JSONResponse) VisitGetThingResponse(w http.ResponseWriter) error {
	return json.NewEncoder(w).Encode(r)
}

// StrictServerInterface represents`, 1)

// TestHalveObjects (M6-01): objects.gen.go is cut at the start of the operation group nearest its
// middle into two valid files, each with only the imports it uses, so neither reaches
// repo.max_file_kb; a file with one group keeps it whole and the second file holds only the
// package clause.
func TestHalveObjects(t *testing.T) {
	_, _, objects, err := splitRest([]byte(splitTwoOpsInput))
	if err != nil {
		t.Fatal(err)
	}
	first, second, err := halveObjects(objects)
	if err != nil {
		t.Fatal(err)
	}
	_, ft, _ := importsOf(t, "objects.gen.go", first)
	si, st, _ := importsOf(t, "objects2.gen.go", second)
	if want := []string{"ListThingsRequestObject", "ListThings200JSONResponse"}; !slices.Equal(ft, want) {
		t.Errorf("first types = %v, want %v", ft, want)
	}
	if want := []string{"GetThingRequestObject", "GetThing200JSONResponse"}; !slices.Equal(st, want) {
		t.Errorf("second types = %v, want %v", st, want)
	}
	if want := []string{"encoding/json", "net/http"}; !slices.Equal(sortedCopy(si), want) {
		t.Errorf("second imports = %v, want %v", si, want)
	}
	_, _, one, err := splitRest([]byte(splitStrictInput))
	if err != nil {
		t.Fatal(err)
	}
	whole, empty, err := halveObjects(one)
	if err != nil {
		t.Fatal(err)
	}
	if _, types, _ := importsOf(t, "objects2.gen.go", empty); len(types) != 0 || len(whole) == 0 {
		t.Errorf("one group: second types = %v", types)
	}
}
